%% BME 3080 - Statistical Analysis: Actin & Microtubules by Well Condition
% One-way ANOVA + Tukey-Kramer post hoc tests
% Requires Statistics and Machine Learning Toolbox

clear; clc; close all;

%% 1. IMPORT DATA
% Assumes a CSV file named 'well_data.csv' containing columns for Wells and measurements
data = readtable('well_data.csv');


% Display variable names and the first few rows
disp('Detected Column Names:'); %[output:4f0cec54]
disp(data.Properties.VariableNames); %[output:8a0eff0d]

disp('First 5 rows:'); %[output:4d7c6e54]
head(data) %[output:432507a9]

% Convert well/condition column to string/categorical if stored as text
data.Well = string(data.Well);

%% =========================================================================
%% PART A: ACTIN ANALYSIS (Wells 3, 4, and 6)
%% =========================================================================

actinWells = ["Well 3", "Well 4", "Well 6"];
treatments = ["UT", "Cyto", "Col"];
actinMeasurements = ["ActinCount", "ActinLength"]; % Adjust column names to match your CSV

for m = 1:length(actinMeasurements) %[output:group:6da103ae]
    
    measurement = actinMeasurements(m);
    fprintf('\n====================================\n'); %[output:70537885] %[output:90eb785f]
    fprintf('ACTIN - %s\n', measurement); %[output:62c77d2c] %[output:93cbec9c]
    fprintf('====================================\n'); %[output:45158c09] %[output:1e12dd27]
    
    values = data.(char(measurement));
    groups = data.Well;
    
    % Remove missing measurements and filter for actin wells
    valid = ~isnan(values) & ismember(groups, actinWells);
    values = values(valid);
    groups = groups(valid);
    
    %% Descriptive Statistics
    means = zeros(1, length(actinWells));
    SDs = zeros(1, length(actinWells));
    sampleSizes = zeros(1, length(actinWells));
    
    for g = 1:length(actinWells)
        groupData = values(groups == actinWells(g));
        
        means(g) = mean(groupData);
        SDs(g) = std(groupData);
        sampleSizes(g) = length(groupData);
        
        fprintf('\n%s:\n', actinWells(g)); %[output:4f4826b4] %[output:6e0bce0b] %[output:40742aad] %[output:036555b9] %[output:921784b1] %[output:503906e8]
        fprintf('Mean = %.3f\n', means(g)); %[output:600fada4] %[output:87b7a1da] %[output:849147e7] %[output:73d7b7b0] %[output:26799ec4] %[output:1e166004]
        fprintf('SD = %.3f\n', SDs(g)); %[output:06dba69b] %[output:6885075a] %[output:3623b908] %[output:5c19f365] %[output:4180ffaf] %[output:54643a1b]
        fprintf('n = %d\n', sampleSizes(g)); %[output:52b9b5d8] %[output:38a21cac] %[output:791d654e] %[output:929d3ea4] %[output:358b21c1] %[output:3258a258]
    end
    
    %% One-Way ANOVA
    if any(sampleSizes < 2)
        warning('Insufficient data for Actin - %s', measurement);
        continue;
    end
    
    [p, tbl, stats] = anova1(values, categorical(groups, actinWells), 'off');
    fprintf('\nANOVA p-value = %.6f\n', p); %[output:5e4a30a0] %[output:48b2f6fc]
    
    if p < 0.05
        fprintf('Significant overall difference across actin wells.\n');
    else
        fprintf('No significant overall difference across actin wells.\n'); %[output:7ac109b0] %[output:7c8a6100]
    end
    
    %% Tukey-Kramer Post Hoc Test
    [comparisonResults, ~] = multcompare(stats, 'CriticalValueType', 'tukey-kramer', 'Display', 'off');
    fprintf('\nTukey-Kramer Comparisons:\n'); %[output:58c16cd2] %[output:1619e32f]
    
    for k = 1:size(comparisonResults, 1)
        group1 = stats.gnames{comparisonResults(k,1)};
        group2 = stats.gnames{comparisonResults(k,2)};
        pPost = comparisonResults(k,6);
        fprintf('%s vs %s: p = %.6f\n', group1, group2, pPost); %[output:06dfe24c] %[output:7b0af814]
    end
    
    %% Graph Mean +/- Standard Deviation
    figure('Color','w', 'Position',[100, 100, 650, 450]); %[output:6bcc7d8e] %[output:1fbd2e9b]
    hold on; %[output:6bcc7d8e] %[output:1fbd2e9b]

    % Define Okabe-Ito Colorblind-Friendly Palette (RGB normalized 0 to 1)
    cbPalette = [
        0.35, 0.70, 0.90;  % Sky Blue
        0.90, 0.60, 0.00;  % Orange
        0.00, 0.60, 0.50;  % Bluish Green
        0.80, 0.40, 0.00   % Vermilion
    ];
    
   
    % Draw Bar Graph for Means

    % Define compressed x-positions (e.g., spacing of 0.6 instead of 1.0)
xPos = 1:0.6:(1 + 0.6 * (length(actinWells) - 1));

    b = bar(xPos, means, 0.30, 'FaceColor', 'flat', 'EdgeColor', 'none');
    for g = 1:length(actinWells)
        b.CData(g, :) = cbPalette(g, :);
    end
    
    errorbar(xPos, means, SDs, '.', 'Color', 'k', 'LineWidth', 1.5, 'MarkerSize', 8, 'CapSize', 12);
    
    
% Overlay Individual Sample Points
    groupsDisplay = groups;
    for g = 1:length(actinWells)
        groupData = values(groups == actinWells(g));
        groupsDisplay(groups == actinWells(g)) = treatments(g);
        xPositions = xPos(g) + linspace(-0.08, 0.08, length(groupData));
        scatter(xPositions, groupData, 45, 'MarkerFaceColor', [0.2 0.2 0.2], ...
            'MarkerEdgeColor', 'k', 'LineWidth', 0.8, 'MarkerFaceAlpha', 0.85);
    end
    
    % Formatting Axes and Labels
    xticks(xPos);
    xticklabels(treatments);
    xlim([xPos(1) - 0.4, xPos(end) + 0.4]);
    ylim([0, max(values) * 1.2]); % Start y-axis at 0 for clear bar scaling
    
    if contains(measurement, "Length")
        ylabel('Mean filament length (\mum)', 'FontSize', 14, 'FontWeight', 'bold');
    else
        ylabel('Filament count per cell', 'FontSize', 14, 'FontWeight', 'bold');
    end
    
    actinTitles = ["Actin Count", "Actin Length"];

    title(sprintf('%s (ANOVA p = %.4f)', actinTitles(m),p), 'FontSize', 16, 'FontWeight', 'bold');
    set(gca, 'FontSize', 14, 'LineWidth', 1.2, 'TickDir', 'out');
    box off;
    hold off;
    
    % Save Figure
    figName = sprintf('Actin_%s.png', measurement);
    exportgraphics(gcf, figName, 'Resolution', 300);
end %[output:group:6da103ae]


%% =========================================================================
%% PART B: MICROTUBULE ANALYSIS (Wells 3, 4, 5, and 6)
%% =========================================================================

microtubuleWells = ["Well 3", "Well 4", "Well 5", "Well 6"];
treatments2 = ["UT", "Cyto", "MeOH","Col"];
microtubuleMeasurement = "MicrotubulePercentArea"; % Adjust column name to match your CSV

fprintf('\n====================================\n'); %[output:21f5a99d]
fprintf('MICROTUBULES - Percent Area\n'); %[output:3d0c2120]
fprintf('====================================\n'); %[output:62b7ddfd]

mtValues = data.(char(microtubuleMeasurement));
mtGroups = data.Well;

% Remove missing measurements and filter for microtubule wells
mtValid = ~isnan(mtValues) & ismember(mtGroups, microtubuleWells);
mtValues = mtValues(mtValid);
mtGroups = mtGroups(mtValid);

%% Descriptive Statistics
mtMeans = zeros(1, length(microtubuleWells));
mtSDs = zeros(1, length(microtubuleWells));
mtSampleSizes = zeros(1, length(microtubuleWells));

for g = 1:length(microtubuleWells) %[output:group:846684a2]
    groupData = mtValues(mtGroups == microtubuleWells(g));
    
    mtMeans(g) = mean(groupData);
    mtSDs(g) = std(groupData);
    mtSampleSizes(g) = length(groupData);
    
    fprintf('\n%s:\n', microtubuleWells(g)); %[output:760d1729] %[output:51b38382] %[output:1bdef5fa] %[output:89968873]
    fprintf('Mean = %.3f\n', mtMeans(g)); %[output:8e633f23] %[output:023204a3] %[output:751ce15c] %[output:6102d92a]
    fprintf('SD = %.3f\n', mtSDs(g)); %[output:3d52dfb2] %[output:63d2c354] %[output:9d5c14ed] %[output:78e65d56]
    fprintf('n = %d\n', mtSampleSizes(g)); %[output:2bf47001] %[output:70ad55fe] %[output:74451627] %[output:2415aa36]
end %[output:group:846684a2]

%% One-Way ANOVA
if ~any(mtSampleSizes < 2) %[output:group:744c7042]
    [mtP, ~, mtStats] = anova1(mtValues, categorical(mtGroups, microtubuleWells), 'off');
    fprintf('\nANOVA p-value = %.6f\n', mtP); %[output:8ce88617]
    
    if mtP < 0.05
        fprintf('Significant overall difference across microtubule wells.\n'); %[output:098146fa]
    else
        fprintf('No significant overall difference across microtubule wells.\n');
    end
    
    %% Tukey-Kramer Post Hoc Test
    [mtComparisonResults, ~] = multcompare(mtStats, 'CriticalValueType', 'tukey-kramer', 'Display', 'off');
    fprintf('\nTukey-Kramer Comparisons:\n'); %[output:934cbdc2]
    
    for k = 1:size(mtComparisonResults, 1)
        group1 = mtStats.gnames{mtComparisonResults(k,1)};
        group2 = mtStats.gnames{mtComparisonResults(k,2)};
        pPost = mtComparisonResults(k,6);
        fprintf('%s vs %s: p = %.6f\n', group1, group2, pPost); %[output:3ae9560a]
    end
    
    %% Graph Bar Chart with Error Bars & Overlay Data Points
    figure('Color', 'w', 'Position', [100, 100, 700, 450]); %[output:0e5bb7a9]
    hold on; %[output:0e5bb7a9]
    
    % Define Okabe-Ito Colorblind-Friendly Palette
    cbPalette = [
        0.35, 0.70, 0.90;  % Sky Blue
        0.90, 0.60, 0.00;  % Orange
        0.00, 0.60, 0.50;  % Bluish Green
        0.80, 0.40, 0.00   % Vermilion
    ];
    
    % Draw Bar Graph for Means

        % Define compressed x-positions (e.g., spacing of 0.6 instead of 1.0)
xPos2 = 1:0.6:(1 + 0.6 * (length(microtubuleWells) - 1));

    b = bar(xPos2, mtMeans, 0.30, 'FaceColor', 'flat', 'EdgeColor', 'none'); %[output:0e5bb7a9]
    for g = 1:length(microtubuleWells)
        b.CData(g, :) = cbPalette(g, :); %[output:0e5bb7a9]
    end
    
    % Add Error Bars (Standard Deviation)
    errorbar(xPos2, mtMeans, mtSDs, '.', 'Color', 'k', ... %[output:0e5bb7a9]
        'LineWidth', 1.8, 'CapSize', 10, 'Marker', 'none'); %[output:0e5bb7a9]
    
    % Overlay Individual Sample Points
    mtgroupsDisplay = mtGroups;
    for g = 1:length(microtubuleWells)
        groupData = mtValues(mtGroups == microtubuleWells(g));
        mtgroupsDisplay(mtGroups == microtubuleWells(g)) = treatments2(g);
        xPositions = xPos2(g) + linspace(-0.08, 0.08, length(groupData));
        scatter(xPositions, groupData, 45, 'MarkerFaceColor', [0.2 0.2 0.2], ... %[output:0e5bb7a9]
            'MarkerEdgeColor', 'k', 'LineWidth', 0.8, 'MarkerFaceAlpha', 0.85); %[output:0e5bb7a9]
    end

%% Graph Bar Chart with Error Bars & Overlay Data Points
    figure('Color','w', 'Position', [100, 100, 700, 450]); %[output:7c1dd648]
    hold on; %[output:7c1dd648]
    
    cbPalette = [
        0.35, 0.70, 0.90;  % Sky Blue
        0.90, 0.60, 0.00;  % Orange
        0.00, 0.60, 0.50;  % Bluish Green
        0.80, 0.40, 0.00   % Vermilion
    ];
    
    % 1. Draw Bars
    xPos = 1:0.6:(1 + 0.6 * (length(microtubuleWells) - 1));
    b = bar(xPos, mtMeans, 0.35, 'FaceColor', 'flat', 'EdgeColor', 'none'); %[output:7c1dd648]
    for g = 1:length(microtubuleWells)
        b.CData(g, :) = cbPalette(g, :); %[output:7c1dd648]
    end
    
    % 2. Draw Error Bars
    errorbar(xPos, mtMeans, mtSDs, '.', 'Color', 'k', ... %[output:7c1dd648]
        'LineWidth', 1.8, 'CapSize', 10, 'Marker', 'none'); %[output:7c1dd648]
    
    % 3. Scatter Data Points
    for g = 1:length(microtubuleWells)
        groupData = mtValues(mtGroups == microtubuleWells(g));
        xPositions = xPos(g) + linspace(-0.04, 0.04, length(groupData));
        scatter(xPositions, groupData, 45, 'MarkerFaceColor', [0.2 0.2 0.2], ... %[output:7c1dd648]
            'MarkerEdgeColor', 'k', 'LineWidth', 0.8, 'MarkerFaceAlpha', 0.85); %[output:7c1dd648]
    end
    
    % 4. Draw Significance Brackets (using mtValues and mtComparisonResults)
    yMax = max(mtValues);
    bracketStep = yMax * 0.08;
    currentY = yMax * 1.00;
    h = yMax + 0.015;
    
    for k = 1:size(mtComparisonResults, 1)
        idx1 = mtComparisonResults(k, 1);
        idx2 = mtComparisonResults(k, 2);
        pVal = mtComparisonResults(k, 6);
        
        if pVal < 0.05
            if pVal < 0.001
                stars = '***';
            elseif pVal < 0.01
                stars = '**';
            else
                stars = '*';
            end
            
            x1 = xPos(idx1);
            x2 = xPos(idx2);
            h = yMax * 0.015;
            
            plot([x1, x1, x2, x2], [currentY, currentY + h, currentY + h, currentY], ... %[output:7c1dd648]
                '-k', 'LineWidth', 1.2, 'HandleVisibility', 'off'); %[output:7c1dd648]
            
            text(mean([x1, x2]), currentY + h, stars, ...
                'HorizontalAlignment', 'center', ...
                'VerticalAlignment', 'bottom', ...
                'FontSize', 12, ...
                'FontWeight', 'bold');
            
            currentY = currentY + bracketStep;
        end
    end
    
    % 5. Formatting & Y-Limits
    xticks(xPos); %[output:7c1dd648]
    xticklabels(treatments2); %[output:7c1dd648]
    xlim([xPos(1) - 0.4, xPos(end) + 0.4]); %[output:7c1dd648]
    ylim([0,1.2]); %[output:7c1dd648]
    yticks(0 : 0.2 : 1.0); %[output:7c1dd648]
    
    ylabel('Percent Area (%)', 'FontSize', 14, 'FontWeight', 'bold'); %[output:7c1dd648]
    t = title(sprintf('Microtubules - Percent Area (ANOVA p = %.4f)', mtP), 'FontSize', 14, 'FontWeight', 'bold'); %[output:7c1dd648]
    set(gca, 'Position', [0.13, 0.11, 0.77, 0.81],'FontSize', 14, 'LineWidth', 1.2, 'TickDir', 'out'); %[output:7c1dd648]
    t.Position(2) = t.Position(2) + (bracketStep * 0.5); %[output:7c1dd648]
    box off; %[output:7c1dd648]
    hold off; %[output:7c1dd648]
    
    % Save Figure
    exportgraphics(gcf, 'Microtubules_PercentArea.png', 'Resolution', 300); %[output:7c1dd648]
 
end %[output:group:744c7042]

fprintf('\nAll analyses complete!\n'); %[output:7bb124f3]

